class NotenRepo:
    def __init__(self, db):
        self.db = db
        db.execute("CREATE TABLE IF NOT"
            " EXISTS noten(fach, note)")
    def speichern(self, fach, note):
        self.db.execute("INSERT INTO"
            " noten VALUES (?, ?)",
            (fach, note))
    def noten_von(self, fach):
        z = self.db.execute("SELECT note"
            " FROM noten WHERE fach = ?",
            (fach,))
        return [r[0] for r in z]

class Zeugnis:
    def __init__(self, repo):
        self.repo = repo
    def schnitt(self, fach):
        n = self.repo.noten_von(fach)
        if not n:
            return None
        return round(sum(n) / len(n), 1)

